#!/usr/bin/env python3import yaml, sys, os, redef clean_str(s):    """Убирает кавычки, пробелы и приводит к нижнему регистру для безопасного сравнения"""    if not isinstance(s, str): return str(s).strip().lower()    return re.sub(r'["\'\s]', '', s).strip().lower()def run_validator():    if len(sys.argv) != 3:        print("❌ Ошибка запуска: нужно 2 аргумента (config.yaml и contract.yaml)")        return False    config_path, contract_path = sys.argv[1], sys.argv[2]        try:        with open(config_path) as f: cfg = yaml.safe_load(f)        with open(contract_path) as f: act = yaml.safe_load(f)    except Exception as e:        print(f"❌ Ошибка чтения файлов: {e}")        return False    # Если контракт обёрнут в BridgeSpec, разворачиваем его    data = act.get("BridgeSpec", act)    print("🔍 Запуск TS-Validator Layer 1-3...")        # === LAYER 1: CoreCheck ===    role_mech = clean_str(data.get("role_binding_protocol", {}).get("mechanism", ""))    if "co-emergent" not in role_mech:        print("❌ CoreCheck FAIL: role_binding_protocol.mechanism должно содержать 'co-emergent'")        return False    print("✅ CoreCheck: PASS")    # === LAYER 2: GammaCheck ===    scope = clean_str(data.get("TPN_Signal_Protocol", {}).get("scope", ""))    if "intersection" not in scope:        print("❌ GammaCheck FAIL: TPN_Signal_Protocol.scope должно содержать 'intersection'")        return False    print("✅ GammaCheck: PASS")    # === LAYER 3: LanguageCheck ===    pipeline = data.get("validation_pipeline", {})    has_layer3 = "layer_3_language" in pipeline    if not has_layer3:        print("❌ LanguageCheck FAIL: отсутствует раздел validation_pipeline.layer_3_language")        return False    print("✅ LanguageCheck: PASS")    print("\n🎉 ИТОГ: VALID (schema_version: 1.1.0)")    return Trueif __name__ == "__main__":    sys.exit(0 if run_validator() else 1)